const rivers = $json.rivers || [];
const high = rivers.filter(r => String(r.risk_level || '').toLowerCase() === 'high').slice(0,5);
if (!high.length) {
  return [{json:{
    pipeline:'river-threshold',
    event_type:'river_check',
    severity:'low',
    title:'River Threshold Stable',
    message:'No high-risk river points in latest cycle.',
    payload:{count_high:0}
  }}];
}
return high.map(r => ({json:{
  pipeline:'river-threshold',
  event_type:'river_escalation',
  severity:'high',
  title:`River Escalation: ${r.name} (${r.city})`,
  message:`${r.name} in ${r.city}, ${r.state} is in HIGH risk state.`,
  location:{lat:r.lat, lon:r.lon},
  radius_km: 160,
  confidence: 0.82,
  payload:r
}}));
